INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(5101, 'Deuteronomy 24:14', 'Deuteronomy', 24, 14, '&nbsp;په خوارو غريبانانو مزدورانو باندې ظلم مۀ کوئ، کۀ هغه اِسرائيلے وى يا مسافر وى چې ستاسو په ښارونو کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5102, 'Deuteronomy 24:15', 'Deuteronomy', 24, 15, '&nbsp;هره ورځ د نمرپرېواتو نه مخکښې هغوئ له خپلې دياړۍ ورکوئ، هغوئ غريبانان دى او پېسو ته يې ضرورت دے. کۀ تاسو هغوئ له پېسې ورنۀ کړئ، نو هغوئ به ستاسو خِلاف مالِک خُدائ ته فرياد وکړى او دا به ستاسو په ګناه کښې حِساب شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5103, 'Deuteronomy 24:16', 'Deuteronomy', 24, 16, '&nbsp;د چا بچو چې جرمونه کړى وى نو د هغې په وجه دې د هغوئ مور پلار نۀ شى وژلے او د چا مور پلار چې جرمونه کړى وى نو د هغې په وجه دې د هغوئ بچى نۀ شى وژلے، هر څوک به صرف د خپلو جرمونو په وجه وژلے شى چې هغوئ په خپله کړى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5104, 'Deuteronomy 24:17', 'Deuteronomy', 24, 17, '&nbsp;مسافر او يتيمان د خپلو حقُونو نه مۀ محرومه کوئ، او د يوې کونډې نه د قرض په ضمانت کښې جامې مۀ اخلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5105, 'Deuteronomy 24:18', 'Deuteronomy', 24, 18, '&nbsp;هغه راياد کړئ چې تاسو په مِصر کښې غلامان وئ او مالِک خُدائ ستاسو خُدائ پاک تاسو آزاد کړئ، نو دا ځکه ما تاسو له دا حُکم درکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5106, 'Deuteronomy 24:19', 'Deuteronomy', 24, 19, '&nbsp;کله چې تاسو خپل فصل راغونډوئ او چې کوم فصل تاسو رېبلے وى او د هغې نه څۀ درنه پاتې شى نو په هغې پسې واپس مۀ ورځئ، دا به مسافرو، يتيمانو او کونډو دپاره پرېښودلے شى، نو داسې مالِک خُدائ ستاسو خُدائ پاک به تاسو له په هغه هر کار کښې برکت درکړى چې تاسو يې کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5107, 'Deuteronomy 24:20', 'Deuteronomy', 24, 20, '&nbsp;کله چې تاسو يو ځل خپل زيتون وشوکوئ، نو هغې له بيا مۀ ورځئ چې هغه پاتې شوى راوشوکوئ، دا به د مسافرو، يتيمانو او کونډو دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5108, 'Deuteronomy 24:21', 'Deuteronomy', 24, 21, '&nbsp;کله چې تاسو يو ځل خپل انګور راټول کړئ، نو په دوېم ځل د انګورو راټولولو دپاره باغونو ته مۀ ځئ، کوم انګور چې پاتې وى نو هغه به د مسافرو، يتيمانو او کونډو دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5109, 'Deuteronomy 24:22', 'Deuteronomy', 24, 22, '&nbsp;دا هيڅکله مۀ هېروئ چې تاسو په مِصر کښې غلامان وئ، نو دا ځکه ما تاسو له دا حُکم درکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5110, 'Deuteronomy 25:1', 'Deuteronomy', 25, 1, '&nbsp;فرض کړئ چې دوه کسان د يوې لانجې هوارولو دپاره عدالت ته لاړ شى او قاضيان فېصله وکړى چې يو په حقه دے او بل په ناحقه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5111, 'Deuteronomy 25:2', 'Deuteronomy', 25, 2, '&nbsp;کۀ په هغه ناحقه کس باندې د وهلو حُکم وشى، نو د قاضى په مخکښې دې هغه پړمخې څملولے شى او په کوړو دې ووهلے شى. هغۀ چې کوم جرم کړے وى نو د کوړو د ګزارونو شمېر به د هغې په مطابق وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5112, 'Deuteronomy 25:3', 'Deuteronomy', 25, 3, '&nbsp;خو هغه به د څلوېښتو کوړو نه زيات نۀ شى وهلے، د څلوېښتو نه زياتو کوړو مطلب به دا وى چې ستاسو ګاونډى د خلقو په مخکښې وشرميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5113, 'Deuteronomy 25:4', 'Deuteronomy', 25, 4, '&nbsp;د غوبل په وخت کښې د غوَيى خولې ته کوَرے مۀ اچوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5114, 'Deuteronomy 25:5', 'Deuteronomy', 25, 5, '&nbsp;کۀ دوه وروڼه يو ځائ اوسيږى او يو د هغوئ نه مړ شى او يو زوئ يې هم پاتې نۀ شى، نو د هغۀ کونډه ښځه به د پردى سړى سره وادۀ نۀ کوى، دا د مړ سړى د ورور ذمه وارى ده چې هغه وادۀ کړى او د هغې سره کوروالے کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5115, 'Deuteronomy 25:6', 'Deuteronomy', 25, 6, '&nbsp;د هغوئ چې وړومبے کوم زوئ پېدا شى نو هغه به د مړ سړى زوئ ګڼلے شى، چې د هغۀ نوم د بنى اِسرائيلو نه ختم نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5116, 'Deuteronomy 25:7', 'Deuteronomy', 25, 7, '&nbsp;خو کۀ د مړ سړى ورور هغې سره وادۀ کول نۀ غواړى، نو هغه ښځه به د ښار مشرانو ته پېش شى او وبه وائى چې زما لېور خپله ذمه وارى نۀ پوره کوى، هغه دا نۀ غواړى چې د هغۀ د ورور نوم په بنى اِسرائيلو کښې باقى پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5117, 'Deuteronomy 25:8', 'Deuteronomy', 25, 8, '&nbsp;نو د ښار مشران دې هغه راوغواړى او د هغۀ سره دې خبره وکړى. کۀ تر اوسه پورې يې وادۀ کول نۀ غواړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5118, 'Deuteronomy 25:9', 'Deuteronomy', 25, 9, '&nbsp;نو د هغۀ د ورور کونډه ښځه دې د ښار د مشرانو په وړاندې هغۀ له ورشى، د هغۀ يوه څپلۍ دې وباسى، د هغۀ په مخ دې توکاڼې اوتُوکى او وبه وائى چې دا هغه څۀ دى چې د هغه سړى سره به کيږى چې د خپل ورور کور آبادول نۀ غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5119, 'Deuteronomy 25:10', 'Deuteronomy', 25, 10, '&nbsp;نو د هغۀ خاندان به په بنى اِسرائيلو کښې په دې نوم ياديږى چې، ”هغه سړے چې څپلۍ يې ويستلے شوې وه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5120, 'Deuteronomy 25:11', 'Deuteronomy', 25, 11, '&nbsp;کۀ دوه سړى په جګړه وى او د هغه يو سړى ښځه د خپل خاوند د مدد کوشش داسې وکړى چې هغه بل سړے د هګو نه راونيسى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5121, 'Deuteronomy 25:12', 'Deuteronomy', 25, 12, '&nbsp;نو چې په هغه ښځه باندې هيڅ رحم ونۀ کړئ، او د هغې لاس پرې کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5122, 'Deuteronomy 25:15', 'Deuteronomy', 25, 15, '&nbsp;صحيح او پوره ناپ تول کوئ، نو داسې به تاسو په هغه مُلک کښې يوه ډېره موده تېره کړئ چې مالِک خُدائ ستاسو خُدائ پاک يې تاسو له درکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5123, 'Deuteronomy 25:16', 'Deuteronomy', 25, 16, '&nbsp;مالِک خُدائ د هغه خلقو نه کرکه کوى چې څوک داسې دوکه مار کارونه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5124, 'Deuteronomy 25:17', 'Deuteronomy', 25, 17, '&nbsp;هغه راياد کړئ چې کله تاسو د مِصر نه راروان وئ نو عماليقيانو درسره څۀ وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5125, 'Deuteronomy 25:18', 'Deuteronomy', 25, 18, '&nbsp;هغوئ د خُدائ پاک نه هيڅ يره نۀ کوله، نو هغوئ په داسې وخت کښې په تاسو د شا نه حمله وکړه چې تاسو ستړى ستومانه وئ او چې کوم وروستو پاتې وُو نو هغه ټول يې ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5126, 'Deuteronomy 25:19', 'Deuteronomy', 25, 19, '&nbsp;نو چې کله مالِک خُدائ ستاسو خُدائ پاک هغه مُلک تاسو له درکړى او د خپلو ټولو دشمنانو نه مو بچ کړى چې ستاسو نه ګېرچاپېره اوسيږى، نو ګورئ چې ټول عماليقيان ووژنئ، نو د آسمان لاندې به هيڅ څوک نور هغوئ نۀ يادوى. دا کار مۀ هېروئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5127, 'Deuteronomy 26:1', 'Deuteronomy', 26, 1, '&nbsp;د هغې نه وروستو چې کله تاسو هغه مُلک قبضه کړئ چې مالِک خُدائ ستاسو خُدائ پاک يې تاسو له درکوى او هلته اوسېږئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5128, 'Deuteronomy 26:2', 'Deuteronomy', 26, 2, '&nbsp;نو تاسو هر يو به خامخا د هر فصل وړومبے برخه په يوه ټوکرۍ کښې ږدئ او دا به د عبادت هغه يو ځائ ته وړۍ چې مالِک خُدائ ستاسو خُدائ پاک يې درته د دې دپاره ښائى چې د هغۀ د نوم درناوے وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5129, 'Deuteronomy 26:3', 'Deuteronomy', 26, 3, '&nbsp;هغه دې د هغه وخت مقرر شوى اِمام له لاړ شى او هغۀ ته دې ووائى چې زۀ مالِک خُدائ خپل خُدائ پاک ته دا اِقرار کوم چې زۀ هغه مُلک ته ورداخل شوم چې زمونږ د پلار نيکۀ سره يې وعده شوې وه چې مونږ له به يې راکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5130, 'Deuteronomy 26:4', 'Deuteronomy', 26, 4, '&nbsp;اِمام به ټوکرۍ ستاسو نه واخلى او هغه به دا د مالِک خُدائ ستاسو د خُدائ پاک د قربان‌ګاه په وړاندې کېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5131, 'Deuteronomy 26:5', 'Deuteronomy', 26, 5, '&nbsp;نو، د مالِک خُدائ په حضور کښې به تاسو دا خبرې بيان کړئ چې، ”زما پلار نيکۀ د شام وو او هغه به لکه د کوچيانو ګرځېدو، هغۀ خپل خاندان مِصر ته بوتلو چې هلته اوسيږى. کله چې هغوئ هلته لاړل نو هغوئ څو کسان وُو، خو د هغوئ نه يو لوئ او طاقتور قوم جوړ شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5132, 'Deuteronomy 26:6', 'Deuteronomy', 26, 6, '&nbsp;د مِصر خلقو مونږ سره بد سلوک کولو او زمونږ نه يې غلامان جوړ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5133, 'Deuteronomy 26:7', 'Deuteronomy', 26, 7, '&nbsp;نو مونږ د خپل پلار نيکۀ مالِک خُدائ ته د مدد دپاره فرياد وکړو. نو هغۀ زمونږ فرياد واورېدو او زمونږ تکليف، سختۍ او غم يې وليدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5134, 'Deuteronomy 26:8', 'Deuteronomy', 26, 8, '&nbsp;د خپل لوئ طاقت او قُدرت سره هغۀ مونږ د مِصر نه راوويستلو. هغۀ معجزې او نښې څرګندې کړې او يروونکى کارونه يې وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5135, 'Deuteronomy 26:9', 'Deuteronomy', 26, 9, '&nbsp;هغۀ مونږ دلته راوستلو او دا مُلک يې راکړو، هغه مُلک چې زرخېز او آباد دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5136, 'Deuteronomy 26:10', 'Deuteronomy', 26, 10, '&nbsp;نو ما مالِک خُدائ له د پېداوار وړومبۍ برخه راوړې ده چې هغۀ ما له د دې زمکې نه راکړې ده.“ نو بيا دا ټوکرۍ د مالِک خُدائ ستاسو خُدائ پاک په وړاندې کېږدئ او د هغۀ په حضور کښې سجده وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5137, 'Deuteronomy 26:11', 'Deuteronomy', 26, 11, '&nbsp;په هغه ښۀ څيزونو شُکر وباسئ چې مالِک خُدائ ستاسو خُدائ پاک تاسو او ستاسو خاندان له درکړى دى، او ليويان او مسافر پرېږدئ کوم چې تاسو سره اوسيږى چې تاسو سره په جشن کښې شامل شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5138, 'Deuteronomy 26:12', 'Deuteronomy', 26, 12, '&nbsp;په هر درېم کال ليويانو، مسافرو، يتيمانو او کونډو له د خپلو فصلونو لسمه برخه ورکوئ، نو داسې ستاسو په هره علاقه کښې به د خوراک ضرورى څيزونه ملاويږى. کله چې تاسو دا وکړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5139, 'Deuteronomy 26:13', 'Deuteronomy', 26, 13, '&nbsp;نو مالِک خُدائ ته ووايئ چې زما په کور کښې د مقدسې لسمې حِصې نه هيڅ نۀ دى پاتې شوى، ما هغه ليويانو، مسافرو، يتيمانو او کونډو له ورکړى دى، لکه څنګه چې تا ما ته حُکم کړے دے. د لسمې حِصې په حقله ما ستا د حُکمونو نه د يو حُکم نافرمانى نۀ ده کړې او نۀ مې هېر کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5140, 'Deuteronomy 26:14', 'Deuteronomy', 26, 14, '&nbsp;کله چې زۀ په غم غمژن وم نو ما د دې نه هيڅ نۀ دى خوړلى، کله چې زۀ ناپاک وم نو ما د دې نه د خپل کور نه بهر هيڅ نۀ دى ويستلى، او ما د دې نه د مړو دپاره نذرانې په توګه هيڅ نۀ دى ورکړى. مالِکه خُدايه، ما ستا تابعدارى کړې ده، د لسمې حِصې په حقله چې تا څۀ حُکم کړے دے نو ما هغه هر څۀ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5141, 'Deuteronomy 26:15', 'Deuteronomy', 26, 15, '&nbsp;په آسمان کښې د خپل مقدس مقام نه لاندې وګوره او خپلو خلقو بنى اِسرائيلو له برکت ورکړه، هغه مُلک له هم برکت ورکړه چې زرخېز او آباد دے کوم چې تا مونږ له راکړے دے، لکه څنګه چې تا زمونږ د پلار نيکۀ سره وعده کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5142, 'Deuteronomy 26:16', 'Deuteronomy', 26, 16, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک نن تاسو ته حُکم کوى چې په دې ټولو حُکمونو او اصُولو باندې عمل کوئ، او د زړۀ د اخلاصه په وفادارۍ سره په دې عمل کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5143, 'Deuteronomy 26:17', 'Deuteronomy', 26, 17, '&nbsp;نن تاسو دا اِقرار کړے دے چې مالِک خُدائ ستاسو خُدائ پاک دے. او تاسو وعده کړې ده چې د هغۀ په لاره به روان يئ او د هغۀ قانون، حُکمونه او اصُول به منئ او د هغۀ فرمانبردارى به کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5144, 'Deuteronomy 26:18', 'Deuteronomy', 26, 18, '&nbsp;مالِک خُدائ نن تاسو خپل قيمتى قوم ګڼلى يئ، لکه څنګه چې هغۀ تاسو سره وعده کړې وه، او هغۀ تاسو له حُکم درکړے دے چې د هغۀ ټول حُکمونه به منئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5145, 'Deuteronomy 26:19', 'Deuteronomy', 26, 19, '&nbsp;هغۀ چې څومره قومونه پېدا کړى دى نو په هغه ټولو کښې به ستاسو مقام اوچت وى، نو ستاسو په وجه به د هغۀ د نوم صِفت او درناوے کيږى. تاسو به هغه قوم يئ چې مالِک خُدائ ستاسو خُدائ پاک ته مقدس وى، لکه څنګه چې هغۀ وعده کړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5146, 'Deuteronomy 27:1', 'Deuteronomy', 27, 1, '&nbsp;بيا موسىٰ او د بنى اِسرائيلو مشرانو خلقو ته وفرمائيل، ”نن چې زۀ کوم اصُول درته ښايم هغه ټول ومنئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5147, 'Deuteronomy 27:2', 'Deuteronomy', 27, 2, '&nbsp;په کومه ورځ چې تاسو د اُردن سيند نه پورې وځئ او هغه مُلک ته ورننوځئ چې مالِک خُدائ ستاسو خُدائ پاک يې تاسو له درکوى، نو هلته لوئ لوئ کاڼى ودروئ او لېو يې کړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5148, 'Deuteronomy 27:3', 'Deuteronomy', 27, 3, '&nbsp;او په هغې باندې دا ټول قانون او خبرې وليکئ. کله چې تاسو هغه مُلک ته ورننوځئ چې پئ او شات په کښې ډېر تېر وى، چې مالِک خُدائ ستاسو د پلار نيکۀ خُدائ پاک ستاسو سره د هغې وعده کړې ده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5149, 'Deuteronomy 27:4', 'Deuteronomy', 27, 4, '&nbsp;او چې تاسو د اُردن بلې غاړې ته واوړئ، نو د عيبال په غرۀ باندې دا کاڼى ودروئ، لکه څنګه چې نن زۀ تاسو له حُکم درکوم او هغه کاڼى لېو کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5150, 'Deuteronomy 27:5', 'Deuteronomy', 27, 5, '&nbsp;هلته د کاڼو يوه داسې قربان‌ګاه جوړه کړئ چې د هغې په جوړولو کښې د اوسپنې هيڅ آوزار استعمال نۀ شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5151, 'Deuteronomy 27:6', 'Deuteronomy', 27, 6, '&nbsp;ځکه چې تاسو مالِک خُدائ ستاسو خُدائ پاک دپاره هره قربان‌ګاه جوړَوئ نو هغه دې د داسې کاڼو نه جوړولے شى چې کټ کړے شوى نۀ وى. هلته به تاسو سوزېدونکې قربانۍ پېش کوئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5152, 'Deuteronomy 27:7', 'Deuteronomy', 27, 7, '&nbsp;او هلته به تاسو قربانى کوئ او خپلې د سلامتۍ نذرانې به خورئ او د مالِک خُدائ ستاسو خُدائ پاک په حضور کښې به شُکر وباسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5153, 'Deuteronomy 27:8', 'Deuteronomy', 27, 8, '&nbsp;په کومو کاڼو باندې چې لېو شوے وى په هغې باندې د خُدائ پاک د قانون هره يوه خبره صفا صفا وليکئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5154, 'Deuteronomy 27:9', 'Deuteronomy', 27, 9, '&nbsp;بيا موسىٰ او د ليوى قبيلې اِمامانو ټولو بنى اِسرائيلو ته ووئيل، ”اے د بنى اِسرائيلو خلقو، خاموش شئ او غوږ ونيسئ. نن تاسو د خپل خُدائ پاک د مالِک خُدائ خپل خلق شوئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5155, 'Deuteronomy 27:10', 'Deuteronomy', 27, 10, '&nbsp;نو د هغۀ تابعدارى کوئ او د هغۀ ټول حُکمونه او قانون پوره کوئ چې نن يې زۀ درکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5156, 'Deuteronomy 27:11', 'Deuteronomy', 27, 11, '&nbsp;بيا هم په هغه ورځ موسىٰ د بنى اِسرائيلو خلقو ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5157, 'Deuteronomy 27:12', 'Deuteronomy', 27, 12, '&nbsp;”د اُردن سيند نه د اوړېدو نه پس به دغه قبيلې د ګِرزيم په غرۀ ودريږى، يعنې د شمعون، ليوى، يهوداه، يساکار، يوسف او بنيامين قبيلې. او دوئ به په خلقو د برکتونو اِعلان کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5158, 'Deuteronomy 27:13', 'Deuteronomy', 27, 13, '&nbsp;نو دغه قبيلې يعنې د روبين، جاد، آشر، زبولون، دان او نفتالى د عيبال په غرۀ ودريږى. او په خلقو به لعنت وائى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5159, 'Deuteronomy 27:14', 'Deuteronomy', 27, 14, '&nbsp;ليويان به دا خبرې په اوچت آواز سره وکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5160, 'Deuteronomy 27:15', 'Deuteronomy', 27, 15, '&nbsp;د خُدائ پاک لعنت دې وى په هغه چا څوک چې د کاڼى، لرګى، يا د ويلې کړے شوے څۀ څيز نه بُت جوړ کړى او په پټه د هغې عبادت کوى، مالِک خُدائ د بُت پرستۍ نه نفرت کوى. نو ټول قوم به په جواب کښې ووائى، آمين.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5161, 'Deuteronomy 27:16', 'Deuteronomy', 27, 16, '&nbsp;د خُدائ پاک لعنت دې وى په هغه چا څوک چې د خپل مور پلار بې‌عزتى کوى. نو ټول قوم به په جواب کښې ووائى، آمين.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5162, 'Deuteronomy 27:17', 'Deuteronomy', 27, 17, '&nbsp;د خُدائ پاک لعنت دې وى په هغه چا څوک چې د ګاونډى د زمکې د حد پوله خوځوى. نو ټول قوم به په جواب کښې ووائى، آمين.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
